CREATE OR REPLACE FUNCTION vinops.set_request_context(p_user_id uuid, p_correlation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'vinops', 'pg_catalog'
AS $function$
BEGIN
  IF p_user_id IS NULL OR p_correlation_id IS NULL THEN
    RAISE EXCEPTION 'REQUEST_CONTEXT_REQUIRED' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM set_config('app.user_id', p_user_id::text, true);
  PERFORM set_config('app.correlation_id', p_correlation_id::text, true);
END;
$function$
